INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist HTTPS eine verschlüsselte Version von HTTP?', 2, '[{"text": "Ja", "correct": true, "because": "HTTPS nutzt TLS/SSL zur Verschlüsselung"}, {"text": "Nein", "correct": false, "because": "HTTPS ist HTTP mit Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Verwendet HTTPS standardmäßig den Port 443?', 2, '[{"text": "Ja", "correct": true, "because": "Port 443 ist der Standardport für HTTPS"}, {"text": "Nein", "correct": false, "because": "443 ist festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann HTTPS ohne Zertifikate funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Zertifikate sind für die Authentifizierung und Verschlüsselung essenziell"}, {"text": "Ja", "correct": false, "because": "Zertifikate sind zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Schützt HTTPS die Datenintegrität?', 2, '[{"text": "Ja", "correct": true, "because": "TLS/SSL stellt sicher, dass Daten nicht verändert werden"}, {"text": "Nein", "correct": false, "because": "Integrität ist ein Hauptmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist HTTPS nur für Webseiten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "HTTPS kann auch für andere Dienste wie APIs genutzt werden"}, {"text": "Ja", "correct": false, "because": "HTTPS ist vielseitig einsetzbar"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schicht des OSI-Modells wird primär von HTTPS genutzt?', 2, '[{"text": "Anwendungsschicht", "correct": true, "because": "HTTPS ist ein Anwendungsprotokoll"}, {"text": "Transportschicht", "correct": false, "because": "TLS/SSL arbeitet darunter"}, {"text": "Netzwerkschicht", "correct": false, "because": "Das wäre IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird von HTTPS zur Verschlüsselung verwendet?', 3, '[{"text": "TLS", "correct": true, "because": "Transport Layer Security ist aktuell (oder SSL älter)"}, {"text": "TCP", "correct": false, "because": "TCP ist nur Transport"}, {"text": "UDP", "correct": false, "because": "UDP ist verbindungslos"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptzweck eines HTTPS-Zertifikats?', 2, '[{"text": "Serverauthentifizierung", "correct": true, "because": "Bestätigt die Identität des Servers"}, {"text": "Datenkomprimierung", "correct": false, "because": "Nicht Aufgabe des Zertifikats"}, {"text": "Fehlerkorrektur", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente stellt die Verschlüsselung bei HTTPS sicher?', 2, '[{"text": "TLS/SSL", "correct": true, "because": "Verschlüsselt die Kommunikation"}, {"text": "HTTP", "correct": false, "because": "HTTP ist unverschlüsselt"}, {"text": "IP", "correct": false, "because": "IP ist darunter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Schlüssel wird bei HTTPS für die symmetrische Verschlüsselung verwendet?', 2, '[{"text": "Sitzungsschlüssel", "correct": true, "because": "Wird während der Sitzung generiert"}, {"text": "Privater Schlüssel", "correct": false, "because": "Für asymmetrische Verschlüsselung"}, {"text": "Öffentlicher Schlüssel", "correct": false, "because": "Für Austausch, nicht Daten"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften bietet HTTPS?', 4, '[{"text": "Vertraulichkeit", "correct": true, "because": "Daten sind verschlüsselt"}, {"text": "Integrität", "correct": true, "because": "Daten bleiben unverändert"}, {"text": "Authentifizierung", "correct": true, "because": "Server wird verifiziert"}, {"text": "Hohe Geschwindigkeit ohne Overhead", "correct": false, "because": "Verschlüsselung erhöht Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum HTTPS-Verbindungsaufbau?', 3, '[{"text": "TLS-Handshake", "correct": true, "because": "Schlüssel werden ausgetauscht"}, {"text": "Zertifikatsprüfung", "correct": true, "because": "Verifiziert den Server"}, {"text": "Datenübertragung ohne Verschlüsselung", "correct": false, "because": "Daten sind verschlüsselt"}, {"text": "Schlüsselaustausch", "correct": true, "because": "Für symmetrische Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für HTTPS notwendig?', 4, '[{"text": "Webserver mit TLS-Unterstützung", "correct": true, "because": "Server muss verschlüsseln"}, {"text": "Gültiges Zertifikat", "correct": true, "because": "Für Authentifizierung"}, {"text": "Browser mit HTTPS-Unterstützung", "correct": true, "because": "Client muss kompatibel sein"}, {"text": "UDP-Protokoll", "correct": false, "because": "HTTPS nutzt TCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet HTTPS gegenüber HTTP?', 3, '[{"text": "Schutz vor Abhören", "correct": true, "because": "Verschlüsselung verhindert Mitlesen"}, {"text": "Verifizierung der Serveridentität", "correct": true, "because": "Zertifikate bestätigen Echtheit"}, {"text": "Schnellere Übertragung", "correct": false, "because": "Verschlüsselung kann langsamer sein"}, {"text": "Schutz vor Datenmanipulation", "correct": true, "because": "Integrität gewährleistet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angriffe verhindert HTTPS?', 3, '[{"text": "Man-in-the-Middle", "correct": true, "because": "Verschlüsselung und Zertifikate schützen"}, {"text": "Phishing durch falsche Zertifikate", "correct": false, "because": "Nur wenn Zertifikate vertrauenswürdig sind"}, {"text": "Eavesdropping", "correct": true, "because": "Daten sind verschlüsselt"}, {"text": "DDoS", "correct": false, "because": "DDoS wird nicht direkt verhindert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) HTTPS nutzt TLS zur Verschlüsselung. b) HTTPS verwendet standardmäßig Port 80.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TLS ja, Port 80 ist für HTTP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) HTTPS schützt die Vertraulichkeit der Daten. b) HTTPS garantiert schnelle Übertragung ohne Overhead.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertraulichkeit ja, Overhead durch Verschlüsselung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) HTTPS erfordert ein Zertifikat von einer CA. b) HTTPS kann über UDP laufen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zertifikat ja, HTTPS nutzt TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) HTTPS verhindert Datenmanipulation. b) HTTPS ist nur für Webseiten gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrität ja, HTTPS ist vielseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) HTTPS nutzt einen TLS-Handshake. b) HTTPS schützt vor allen Cyberangriffen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Handshake ja, nicht alle Angriffe verhindert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

